function palindromeCuts(s: string): string[][] {
  const n = s.length;
  const out: string[][] = [];
  const pieces: string[] = [];
  const isPal = (i: number, j: number): boolean => {
    while (i < j) if (s[i++] !== s[j--]) return false;
    return true;
  };
  const go = (start: number): void => {
    if (start === n) { out.push([...pieces]); return; }
    for (let end = start; end < n; end++) {
      if (!isPal(start, end)) continue;
      pieces.push(s.slice(start, end + 1));
      go(end + 1);
      pieces.pop();
    }
  };
  go(0);
  return out;
}

