class Solution:
    def palindromeCuts(self, s: str) -> List[List[str]]:
        n = len(s)
        out, pieces = [], []

        def go(start: int) -> None:
            if start == n:
                out.append(pieces[:])
                return
            for end in range(start, n):
                piece = s[start:end + 1]
                if piece != piece[::-1]:
                    continue
                pieces.append(piece)
                go(end + 1)
                pieces.pop()

        go(0)
        return out

