function palindromeCuts(s: string): string[][] {
  const n = s.length;
  const pal: boolean[][] = Array.from({ length: n }, () => new Array<boolean>(n).fill(false));
  for (let i = n - 1; i >= 0; i--)
    for (let j = i; j < n; j++)
      pal[i][j] = s[i] === s[j] && (j - i < 2 || pal[i + 1][j - 1]); // needs the inner range first
  const out: string[][] = [];
  const pieces: string[] = [];
  const go = (start: number): void => {
    if (start === n) { out.push([...pieces]); return; }
    for (let end = start; end < n; end++) {
      if (!pal[start][end]) continue;
      pieces.push(s.slice(start, end + 1));
      go(end + 1);
      pieces.pop();
    }
  };
  go(0);
  return out;
}

